import 'package:flutter/material.dart';import '../../core/network/api.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key,required this.api});final ClyraApi api;@override State<NotificationsScreen> createState()=>_NotificationsScreenState();}
class _NotificationsScreenState extends State<NotificationsScreen>{late Future<dynamic> future;@override void initState(){super.initState();reload();}void reload(){setState(()=>future=widget.api.get('/notifications?limit=100'));}
@override Widget build(BuildContext context)=>FutureBuilder<dynamic>(future:future,builder:(context,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return Center(child:Text('Unable to load notifications: ${s.error}'));final notifications=(s.data as List?)??[];if(notifications.isEmpty)return const Center(child:Text('No notifications yet.'));return ListView(children:[for(final n in notifications)Card(child:ListTile(leading:Icon(n['isRead']==true?Icons.notifications_none:Icons.notifications_active,color:Theme.of(context).colorScheme.primary),title:Text(n['title']??''),subtitle:Text(n['message']??''),onTap:()async{await widget.api.patch('/notifications/${n['_id']}/read',{});reload();}))]);});}
